import {decimalValidator} from './decimal-validator';

// all tests were entirely generated by claude
describe('decimalValidator(11, 2)', () => {
    const validator = decimalValidator(11, 2);

    it('accepts value with two decimals', () => {
        expect(validator('1246,50')).toBeNull();
    });

    it('accepts negative value with minus on the right', () => {
        expect(validator('1246,50-')).toBeNull();
    });

    it('accepts zero', () => {
        expect(validator('0,00')).toBeNull();
    });

    it('accepts one decimal', () => {
        expect(validator('12,5')).toBeNull();
    });

    it('accepts value without comma', () => {
        expect(validator('12')).toBeNull();
    });

    it('accepts leading zeros', () => {
        expect(validator('00012,50')).toBeNull();
    });

    it('accepts exactly 11 digits before the comma', () => {
        expect(validator('12345678901,00')).toBeNull();
    });

    it('rejects letters', () => {
        expect(validator('abc')).toEqual(expect.any(String));
    });

    it('rejects empty string', () => {
        expect(validator('')).toEqual(expect.any(String));
    });

    it('rejects leading space', () => {
        expect(validator(' 12,50')).toEqual(expect.any(String));
    });

    it('rejects trailing space', () => {
        expect(validator('12,50 ')).toEqual(expect.any(String));
    });

    it('rejects minus on the left', () => {
        expect(validator('-12,50')).toEqual(expect.any(String));
    });

    it('rejects double minus', () => {
        expect(validator('12,50--')).toEqual(expect.any(String));
    });

    it('rejects plus sign', () => {
        expect(validator('12,50+')).toEqual(expect.any(String));
    });

    it('rejects comma without decimals', () => {
        expect(validator('12,')).toEqual(expect.any(String));
    });

    it('rejects comma without integer part', () => {
        expect(validator(',50')).toEqual(expect.any(String));
    });

    it('rejects dot as separator', () => {
        expect(validator('12.50')).toEqual(expect.any(String));
    });

    it('rejects two commas', () => {
        expect(validator('1,2,3')).toEqual(expect.any(String));
    });

    it('rejects 12 digits before the comma', () => {
        expect(validator('123456789012,00')).toEqual(expect.any(String));
    });

    it('rejects 3 digits after the comma', () => {
        expect(validator('12,345')).toEqual(expect.any(String));
    });
});

describe('decimalValidator(2, 2) as used for tax rate', () => {
    const validator = decimalValidator(2, 2);

    it('accepts 19,00', () => {
        expect(validator('19,00')).toBeNull();
    });

    it('rejects 100,00 (three digits before the comma)', () => {
        expect(validator('100,00')).toEqual(expect.any(String));
    });
});